'use strict';
const M=globalThis.CatapultModel;
const $=s=>document.querySelector(s);
const state={i:Math.max(0,(parseInt(location.hash.slice(1))||1)-1),A:0,B:1,C:1,D:0,branch:1,compose:0,trace:false,motion:!globalThis.matchMedia?.('(prefers-reduced-motion: reduce)').matches,scanning:false,scan:0};
let timer=null;
const sourcePaper='Gaede et al., CATAPULT, DAC 1988, pp. 597–600, Sections 2.3 and 3.1–3.4.';
const sourceBook='Bushnell & Agrawal, Essentials of Electronic Testing, printed pp. 158–162 and 204.';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=(label,h,p='')=>`<div class="slide-title"><span class="eyebrow">${label}</span><h2>${h}</h2>${p?`<p class="subtitle">${p}</p>`:''}</div>`;
const layout=(left,right,cls='')=>`<div class="layout ${cls}"><div>${left}</div><div>${right}</div></div>`;
const eq=(label,value)=>`<div class="equation"><span class="formula-label">${label}</span><div class="formula">${value}</div></div>`;
const note=s=>`<p class="callout">${s}</p>`;
const chips=(labels=['A','B','C','D'])=>`<div class="interactive-label">CLICK THE INPUTS TO EXPLORE</div><div class="switches">${labels.map(v=>`<button class="bit ${state[v]?'on':''}" data-bit="${v}" aria-label="Toggle ${v}" aria-pressed="${!!state[v]}"><small>${v}</small>${state[v]}</button>`).join('')}</div>`;
const values=()=>({...state,S:state.A^state.B});
const svg=(body,label,box='0 0 660 370')=>`<svg class="diagram" viewBox="${box}" role="img" aria-label="${label}">${body}</svg>`;
function graph(key,{active=false,selected=null}={}){
 const b=M.graphs[key],x=selected||values(),g=M.diagram(b),t=M.trace(b,x);
 const step=active?Math.min(state.traceStep??t.steps.length,t.steps.length):0,shown=t.steps.slice(0,step),nodes=new Set([b.root,...shown.map(s=>s.to)]);
 let lines='',circles='',route=`M${g.pos.get(b.root).x} ${g.pos.get(b.root).y}`;
 for(const edge of g.edges){const on=active&&shown.some(s=>s.from===edge.from&&s.to===edge.to&&s.bit===edge.bit);
  lines+=`<path class="branch ${edge.bit?'':'low'} ${on?'active-path':''}" data-from="${edge.from}" data-to="${edge.to}" data-bit-value="${edge.bit}" d="${edge.d}"/><circle class="edge-badge" cx="${edge.label.x}" cy="${edge.label.y-5}" r="12"/><text class="edge-label" x="${edge.label.x}" y="${edge.label.y}" text-anchor="middle">${edge.bit}</text>`;
 }
 for(const id of g.reachable){const n=b.nodes[id],p=g.pos.get(id),hot=active&&nodes.has(id);circles+=n.variable?`<circle class="node ${hot?'hot':''}" cx="${p.x}" cy="${p.y}" r="26"/><text class="bdd-label" x="${p.x}" y="${p.y+7}" text-anchor="middle">${n.variable}</text>`:`<rect class="terminal-node ${hot?'hot':''}" x="${p.x-31}" y="${p.y-26}" width="62" height="52" rx="9"/><text class="bdd-label" x="${p.x}" y="${p.y+7}" text-anchor="middle">${n.value}</text>`;}
 for(const s of shown){const edge=g.edges.find(e=>e.from===s.from&&e.bit===s.bit);route+=`L${edge.start.x} ${edge.start.y}`+edge.d.replace(/^M[^C]+/,'')+`L${g.pos.get(s.to).x} ${g.pos.get(s.to).y}`;}
 if(active&&shown.length)circles+=`<circle class="bdd-runner" r="7"><animateMotion dur="${1+shown.length*.7}s" repeatCount="indefinite" path="${route}"/></circle>`;
 const trail=t.steps.map((s,i)=>`<span class="${active&&i<step?'visited':''}">${s.variable}=${s.bit}</span>`).join('<i>›</i>');
 const complete=active&&step===t.steps.length;
 return `<div class="graph-frame" data-graph="${key}" data-result="${t.value}" data-progress="${step}">${svg(lines+circles,`${key} BDD. Dashed branches mean 0; solid branches mean 1.`,'0 0 660 440')}<div class="graph-caption"><span>ORDER ${b.order.join(', ')}</span><span>${g.reachable.size-2} decisions</span></div>${active?`<div class="path-readout">${trail}<i>›</i><strong class="${complete?'reached':''}">${complete?'Terminal '+t.value:'Continue tracing'}</strong></div>`:''}</div>`;
}
const legend=()=>'<div class="legend"><span><i class="dash"></i>0 branch</span><span><i></i>1 branch</span></div>';
function circuit({fault=false}={}){
 const x=values(),r=M.simulate(x),S=fault?0:x.S,top=S&x.C,bottom=(1-S)&x.D;
 const wire=(d,on)=>`<path class="${on?'live':'wire'}" data-signal="${on?1:0}" d="${d}"/>`;
 return svg(`
 ${wire('M20 140H105',x.A)}${wire('M20 200H105',x.B)}${wire('M208 170H280V95H355',S)}${wire('M280 170V250H302',S)}${wire('M20 40H330V55H355',x.C)}${wire('M20 315H330V285H355',x.D)}${wire('M340 250H355',1-S)}${wire('M445 75H485V155H538',top)}${wire('M445 265H485V195H538',bottom)}${wire('M605 175H645',top|bottom)}
 <rect class="gate" x="105" y="117" width="103" height="106" rx="13"/><text x="142" y="178" text-anchor="middle">XOR</text>
 <path class="gate" d="M355 25H395A50 50 0 0 1 395 125H355Z"/><text x="390" y="82" text-anchor="middle">AND</text>
 <path class="gate" d="M355 215H395A50 50 0 0 1 395 315H355Z"/><text x="390" y="272" text-anchor="middle">AND</text>
 <path class="gate" d="M302 235L328 250L302 265Z"/><circle class="node" cx="334" cy="250" r="6"/>
 <path class="gate" d="M530 135Q565 135 605 175Q565 215 530 215Q550 175 530 135Z"/><text x="568" y="182" text-anchor="middle">OR</text>
 <circle cx="280" cy="170" r="5" fill="var(--green)"/><text x="20" y="126">A=${x.A}</text><text x="20" y="224">B=${x.B}</text><text x="20" y="28">C=${x.C}</text><text x="20" y="340">D=${x.D}</text><text x="239" y="151" class="stem-label">S=${S}</text><text x="612" y="152">F=${top|bottom}</text>
 ${fault?'<text x="225" y="199" class="fault-label">s-a-0</text>':''}
 `,fault?'Circuit with S stuck at zero':'Good circuit with XOR fanout stem S');
}
const traceControls=()=>`<div class="trace-controls"><button class="action-small" id="traceBDD">${state.trace?'Reset trace':'Trace whole path'}</button><button class="action-small" id="nextDecision">Next decision</button></div>`;
const foot=(s)=>`<p class="micro">${s}</p>`;
const slides=[];
function add(name,chapter,label,notes,render,source=sourcePaper){slides.push({name,chapter,section:label,notes,render,source});}
add('CATAPULT: circuit to test',0,'CATAPULT',
 'This presentation spends two slides revising the mathematics, then follows one new teaching circuit through the original CATAPULT workflow. The example is original to this revised deck. It is not taken from the paper or either previous group deck.',()=>layout(`<div class="cover-copy"><span class="eyebrow">DIGITAL TEST LAB / COE529</span><h1>CATA<span class="accent">PULT</span></h1><p class="hero-sub">ONE CIRCUIT. EVERY STEP EXPLAINED.</p><p class="subtitle">From a target fault to a BDD,<br>then to an input you can apply.</p><button class="start" data-go="1">Start the walkthrough</button><p class="micro">Concurrent Automatic Testing Allowing<br>Parallelization and Using Limited Topology</p></div>`,`<div class="cover-art">${graph('final',{active:true,selected:{A:0,B:1,C:1,D:0}})}<span class="cover-sticker">NEW EXAMPLE<br><strong>test = 0110</strong></span></div>`));
add('The route through CATAPULT',0,'THE ROUTE',
 'Orient the class. A gate-level combinational circuit and target fault enter the process. A forward pass computes switching functions. A backward pass computes observability. Test BDDs combine activation with propagation. Partial composition obtains a consistent test in primary inputs. These phases are not a claim of constant or linear total cost.',()=>layout(title('THE MAIN IDEA','A function for<br><span class="accent">the valid tests</span>','We will follow S stuck-at-0 through one four-input circuit.'),`<div class="route-list">${[['Forward pass','Store the circuit functions'],['Backward pass','Compute when a fault is observable'],['BDD AND','Combine activation and observability'],['Partial composition','Resolve the stem into real inputs'],['Verification','Compare the good and faulty outputs']].map((v,i)=>`<div class="route-item"><span>${i+1}</span><div><h3>${v[0]}</h3><p>${v[1]}</p></div></div>`).join('')}</div>`));
add('Quick revision: Boolean difference',1,'QUICK REVISION',
 'Only a revision. Plus means OR, juxtaposition means AND, prime means NOT, and XOR is 1 when its inputs differ. A Boolean difference compares the two cofactors of an output with respect to the fault site. For S stuck-at-0 the good S must equal 1, and at least one output must depend on it. T=1 marks detecting inputs, not necessarily a circuit output of 1.',()=>layout(title('REVISION / BOOLEAN DIFFERENCE','Does changing S<br>change the output?')+eq('OBSERVABILITY','O<sub>S</sub> = F|<sub>S=0</sub> ⊕ F|<sub>S=1</sub>')+note('XOR = 1 when the two output values differ.'),`<div class="equation-stack">${eq('ACTIVATE S STUCK-AT-0','S = 1')}${eq('DETECT THE FAULT','T₀ = S · O<sub>S</sub>')}</div><table class="mini-table"><tr><th>First output</th><th>Second output</th><th>XOR</th></tr><tr><td>0</td><td>0</td><td>0</td></tr><tr><td>0</td><td>1</td><td class="accent">1</td></tr><tr><td>1</td><td>0</td><td class="accent">1</td></tr><tr><td>1</td><td>1</td><td>0</td></tr></table>`),sourceBook);
add('Quick revision: Shannon expansion',1,'QUICK REVISION',
 'Restriction means setting a variable to a constant. F|x=0 and F|x=1 are cofactors. Shannon expansion reconstructs the function by selecting the appropriate cofactor. Composition replaces a variable by another function; it is different from restriction. The BDD view is a decision node with two branches.',()=>layout(title('REVISION / SHANNON EXPANSION','One variable.<br>Two cases.')+eq('SPLIT ABOUT x','F = x′F|<sub>x=0</sub> + xF|<sub>x=1</sub>')+note('A BDD repeats this split and shares equivalent subgraphs.'),`<div class="shannon-visual"><div class="decision-bubble">x</div><div class="shannon-branches"><div><b>0</b><p>Use F|<sub>x=0</sub></p><small>The x′ term selects this case</small></div><div><b>1</b><p>Use F|<sub>x=1</sub></p><small>The x term selects this case</small></div></div></div>`),sourceBook);
add('Meet the new circuit',2,'OUR CIRCUIT',
 'A new teaching example: S=A XOR B and F=SC+S′D. S is the output of an XOR and a genuine fanout stem: it reaches both AND branches, with an inverter on one branch. C and D are data inputs. S selects C when 1 and D when 0. The target is the stem S stuck-at-0, which affects both branches consistently. This circuit differs from the previous group’s five-input AND-based example.',()=>layout(title('NEW TEACHING EXAMPLE','An XOR-controlled<br><span class="accent">selector</span>')+eq('FANOUT STEM','S = A ⊕ B')+eq('OUTPUT','F = SC + S′D')+foot('A, B, C, D are primary inputs. S is internal.'),circuit()+note('S = 1 selects C. S = 0 selects D.')));
add('Define the target fault',2,'OUR CIRCUIT',
 'Target S stuck-at-0. The good stem must be 1 for activation. Forcing the stem to zero selects D in the faulty circuit. This is a fault on the stem, not just one branch. We do not yet choose the test input; the algorithm derives it.',()=>layout(title('TARGET FAULT','S is stuck at 0','Choose primary inputs that make the good and faulty outputs disagree.')+eq('FAULTY CIRCUIT OUTPUT','F<sub>faulty</sub> = 0·C + 1·D = D')+note('We must activate S = 1 and make C differ from D.'),circuit({fault:true})));
add('A BDD node is a Shannon split',2,'READING THE BDDS',
 'The main algorithm will store functions as BDDs. Dashed edges are 0, solid edges are 1. In S=A XOR B, A=0 leaves B, while A=1 leaves B′. With order A,B this produces one A decision and two different B decisions, sharing terminal 0 and 1. A path to 1 means S=1 here, not yet a full fault test.',()=>layout(title('BDD CONSTRUCTION','The stem as<br>a decision graph')+eq('RESTRICT A TO 0','S|<sub>A=0</sub> = B')+eq('RESTRICT A TO 1','S|<sub>A=1</sub> = B′')+legend(),graph('stem')+foot('This graph represents S, not the final test function.')));
add('Reduce and share the graph',2,'READING THE BDDS',
 'Reduction rules: merge identical subgraphs, including identical terminals, and remove a variable node when both branches point to the same child. Fixed order plus these rules produces a canonical reduced ordered BDD. The example graph is constructed from its Boolean function by the app rather than drawn to imitate one. A and B cannot be removed because their two cofactors differ.',()=>layout(title('BDD REDUCTION','Keep only decisions<br>that change the answer')+`<div class="route-list"><div class="route-item"><span>1</span><div><h3>Share equivalent subgraphs</h3><p>All identical results point to the same node.</p></div></div><div class="route-item"><span>2</span><div><h3>Skip an irrelevant variable</h3><p>If both branches give the same function, remove that decision.</p></div></div></div>`+note('The chosen variable order remains fixed along each path.'),graph('stem')+foot('Two B nodes remain: one represents B, the other B′.')));
add('Forward pass: controllability',3,'FORWARD PASS',
 'In CATAPULT, controllability is a switching function. At each point compute a function from its inputs. Store the XOR function for S and retain S as an explicit variable in the output function. The forward pass proceeds from primary inputs toward outputs. The displayed BDDs represent S and F separately, not numerical SCOAP scores.',()=>`${title('FORWARD PASS','Store functions at the stem and output')}<div class="dual-graphs"><div>${eq('STEM CONTROLLABILITY','CC(S) = A ⊕ B')}${graph('stem')}</div><div>${eq('OUTPUT FUNCTION','F(S,C,D) = SC + S′D')}${graph('output')}</div></div>`);
add('Keep the fanout stem explicit',3,'FORWARD PASS',
 'This is functional decomposition: retain S rather than expanding A XOR B in every downstream expression immediately. S is only symbolically independent during decomposition. A physical chip does not let us set S independently. The later composition phase restores S=A XOR B. This can save work but does not guarantee small BDDs on every circuit.',()=>layout(title('FUNCTIONAL DECOMPOSITION','Keep S named<br>until we need its inputs')+eq('STORED DEFINITION','S = A ⊕ B')+eq('DOWNSTREAM VIEW','F = SC + S′D')+note('S is a temporary symbolic variable. Its defining equation must be enforced before returning a test.'),`<div class="decomposition"><div class="decomp-block"><small>UPSTREAM</small><strong>A ⊕ B</strong><span>Primary inputs A, B</span></div><div class="stem-token">S</div><div class="decomp-block"><small>DOWNSTREAM</small><strong>SC + S′D</strong><span>Stem S and inputs C, D</span></div></div>`));
add('Backward pass: restrict S to zero',4,'BACKWARD PASS',
 'Start the backward pass at the output. Its own observability is 1. To compute observability of S, compare cofactors. With S=0, SC vanishes and S′D becomes D. In the output BDD, choose the 0 edge at S. The remaining function is D; C is irrelevant in that cofactor.',()=>layout(title('BACKWARD PASS / FIRST COFACTOR','Force S to 0')+eq('SUBSTITUTE INTO THE OUTPUT','F|<sub>S=0</sub> = 0·C + 1·D')+eq('RESULT','F|<sub>S=0</sub> = D')+note('Follow S’s 0 branch. Only the decision on D remains.'),graph('co0')+foot('C disappears because it cannot affect this cofactor.')));
add('Backward pass: restrict S to one',4,'BACKWARD PASS',
 'With S=1, SC becomes C and S′D vanishes. Follow the 1 edge at S in the output BDD. The remaining function is C, independent of D. Restriction fixes a variable to a value; it does not substitute a nonconstant function.',()=>layout(title('BACKWARD PASS / SECOND COFACTOR','Force S to 1')+eq('SUBSTITUTE INTO THE OUTPUT','F|<sub>S=1</sub> = 1·C + 0·D')+eq('RESULT','F|<sub>S=1</sub> = C')+note('Follow S’s 1 branch. Only the decision on C remains.'),graph('co1')+foot('D disappears because it cannot affect this cofactor.')));
add('Observability is the XOR of cofactors',4,'BACKWARD PASS',
 'XOR the cofactor BDDs: D XOR C. S is observable exactly when C and D differ. If C=D, flipping S only changes which equal value is selected, so the fault effect is masked. This is the one normal propagation condition in our main example, not a separate edge-case lecture.',()=>layout(title('BDD XOR / OBSERVABILITY','Can the output<br>see S change?')+eq('COMPARE BOTH COFACTORS','CO(S) = D ⊕ C')+chips(['C','D'])+note('Different C and D: observable. Equal C and D: masked.')+legend(),graph('observable',{active:state.trace})+traceControls()));
add('Activation BDD for S stuck-at-zero',5,'BUILD THE TEST BDD',
 'For S stuck-at-0 the good S must be 1. The activation function is CC(S)=A XOR B. In decomposed coordinates activation can be written S, retaining the separate definition S=A XOR B. Do not equate the symbolic variable with a free physical input.',()=>layout(title('ACTIVATION','The good S<br>must equal 1')+eq('ACTIVATION IN THE DECOMPOSED VIEW','Activation = S')+eq('STORED DEFINITION','CC(S) = A ⊕ B')+note('A and B must differ. We will enforce that requirement during composition.'),graph('stem')+foot('The activation BDD over primary inputs is A ⊕ B.')));
add('AND activation and observability',5,'BUILD THE TEST BDD',
 'Compute the test condition for S stuck-at-0: activation S AND observability C XOR D. This graph uses variable order S,C,D and is over decomposed variables. It has candidate paths S=1,C=0,D=1 and S=1,C=1,D=0. A path to 1 here is a candidate, because S has not yet been resolved to primary inputs.',()=>layout(title('BDD AND / TEST DIAGRAM','Activation meets<br>observability')+eq('COMBINE THE CONDITIONS','T₀(S,C,D) = S(C ⊕ D)')+note('The result still contains S. A path to 1 is a candidate until S = A ⊕ B is enforced.')+legend(),graph('test')+foot('BDD AND combines functions; it is not simply joining two pictures.')));
add('Choose one candidate path',5,'BUILD THE TEST BDD',
 'Choose one path to terminal 1. S=1,C=1,D=0 is our starting candidate. Click the alternative to see S=1,C=0,D=1. Either candidate still has an internal variable. The graph is exact in its decomposed variables but not yet an applicable primary-input vector.',()=>layout(title('READ THE TEST BDD','Choose a route<br>to terminal 1')+`<div class="tabs"><button data-branch="1" class="${state.branch?'selected':''}">S=1, C=1, D=0</button><button data-branch="0" class="${!state.branch?'selected':''}">S=1, C=0, D=1</button></div>`+eq('CANDIDATE REQUIREMENTS',`S = 1, C = ${state.branch}, D = ${1-state.branch}`)+note('A and B are not assigned yet. The next step will produce them.'),graph('test',{active:true,selected:{S:1,C:state.branch,D:1-state.branch}})));
add('Partial composition: expand the stem',6,'PARTIAL COMPOSITION',
 'The candidate requires S=1. Look up the stored stem definition S=A XOR B. Resolve that one requirement by following a path to terminal 1 in the stem BDD. A=0 leaves S=B, so choosing B=1 gives S=1. This uses the same function previously computed in the forward pass. The displayed trace is a path-level teaching view of partial composition, not a full implementation of the original CATAPULT scheduler.',()=>{const stages=[['Candidate needs S=1','Keep C=1 and D=0 from the selected candidate.'],['Expand S = A ⊕ B','Only resolve the stem requirement on this candidate path.'],['Choose A=0, then B=1','The stem BDD reaches 1. S=1 is now justified.'],['Return A B C D = 0 1 1 0','Only primary inputs remain. This is an applicable test.']];return layout(title('PARTIAL COMPOSITION','Replace “S = 1”<br>with actual inputs')+`<div class="step-list">${stages.map((s,i)=>`<button data-compose="${i}" class="${state.compose===i?'selected':''}"><span>${i+1}</span>${s[0]}</button>`).join('')}</div><p class="flat-note">${stages[state.compose][1]}</p>`,`${graph(state.compose===0?'test':'stem',{active:true,selected:state.compose===0?{S:1,C:1,D:0}:{A:0,B:1}})}${eq('CURRENT REQUIREMENTS',state.compose<2?'S=1, C=1, D=0':state.compose===2?'A=0, B=1, C=1, D=0':'ABCD = 0110')}`);});
add('Why the composition is partial',6,'PARTIAL COMPOSITION',
 'Full composition would resolve S across the complete test function, yielding all tests in primary inputs. Partial composition follows selected candidate paths and can stop when a valid primary-input path is found. We chose S=1,C=1,D=0 and resolved S through A=0,B=1. Other paths such as A=1,B=0 or the other C,D pair are unnecessary to produce one test. This does not mean alternative paths never need exploration; failed paths may require alternatives, which are deferred to a later edge-case expansion.',()=>layout(title('ONE TEST IS ENOUGH TO RETURN','We resolved<br>one successful path')+eq('CANDIDATE','S=1, C=1, D=0')+eq('EXPAND S ON THAT PATH','A=0, B=1')+eq('RESULT','ABCD = 0110'),`<div class="composition-choice"><div class="chosen"><small>EXPANDED NOW</small><strong>A=0, B=1</strong><p>A path that establishes S=1</p></div><div><small>ALTERNATIVES REMAIN</small><strong>A=1, B=0</strong><p>No need to expand this to return the first test.</p></div></div>`+note('Partial means selected paths are expanded, rather than fully expanding every possible test.')));
add('The final primary-input test BDD',6,'PARTIAL COMPOSITION',
 'For explanation and validation, show the fully composed result T(A,B,C,D)=(A XOR B)(C XOR D). The graph uses order A,B,C,D. A and B must differ; C and D must differ. The whole graph represents four test vectors. CATAPULT need not fully construct this graph just to obtain one test via partial composition. This slide deliberately distinguishes the full explanatory result from the minimum work needed to return one test.',()=>layout(title('FULL RESULT / FOR COMPARISON','All tests in<br>primary inputs')+eq('SUBSTITUTE S = A ⊕ B','T₀ = (A ⊕ B)(C ⊕ D)')+chips()+traceControls()+note('This full graph shows all tests. Partial composition can return 0110 before resolving every alternative.'),graph('final',{active:state.trace})+legend()));
add('Verify the generated test',7,'VERIFICATION',
 'Apply 0110. A=0,B=1 gives S=1. Good F=1·1+0·0=1. The faulty stem is stuck at 0, so faulty F=0·1+1·0=0. The outputs differ. The test function being 1 means detection, not that the good output must always be 1: the other valid test 0101 gives good F=0 and faulty F=1.',()=>layout(title('APPLY ABCD = 0110','The outputs<br><span class="accent">disagree</span>')+eq('GOOD STEM','S = 0 ⊕ 1 = 1')+eq('GOOD OUTPUT','F = 1·1 + 0·0 = 1')+eq('FAULTY OUTPUT','F<sub>faulty</sub> = 0·1 + 1·0 = 0'),`<div class="verify-display"><div><small>GOOD F</small><strong>1</strong></div><span>⊕</span><div><small>FAULTY F</small><strong>0</strong></div></div><div class="test-success">✓ 1 ⊕ 0 = 1 · FAULT DETECTED</div>`));
add('Explore all sixteen inputs',7,'LIVE TEST LAB',
 'This lab exhaustively simulates the four-input teaching circuit and compares the results with the final test function and BDD. The four tests are 0101,0110,1001,1010. Select an input row or toggle the switches. Run all inputs cycles sixteen vectors once and stops. This lab is a teaching model and BDD demonstrator, not a production CATAPULT engine.',()=>{const r=M.simulate(values()),v=state.A*8+state.B*4+state.C*2+state.D;return layout(title('LIVE TEST LAB','Try the generated<br>test yourself')+chips()+circuit()+`<div class="readout"><div><small>GOOD F</small><b>${r.F}</b></div><div><small>FAULTY F</small><b>${r.faulty}</b></div><div><small>TEST T</small><b class="${r.detected?'detected':'blocked'}">${r.detected}</b></div></div><div class="lab-controls"><button class="action-small" id="scan">${state.scanning?'Pause scan':'Run all 16 inputs'}</button><span class="run-status">${state.scanning?`Vector ${state.scan+1} / 16`:'Target: S stuck-at-0'}</span></div>`,`<div class="truth-scroll"><table class="truth"><thead><tr><th>ABCD</th><th>S</th><th>Good F</th><th>Faulty F</th><th>T</th></tr></thead><tbody>${Array.from({length:16},(_,i)=>{const x={A:i>>3,B:(i>>2)&1,C:(i>>1)&1,D:i&1},r=M.simulate(x);return `<tr data-vector="${i}" tabindex="0" role="button" aria-label="Apply ${i.toString(2).padStart(4,'0')}" class="${v===i?'current':''}"><td>${i.toString(2).padStart(4,'0')}</td><td>${r.S}</td><td>${r.F}</td><td>${r.faulty}</td><td class="${r.T?'test':''}">${r.T?'1 ✓':'0'}</td></tr>`;}).join('')}</tbody></table></div>`,'simulator');});
add('The complete walkthrough',8,'RECAP',
 'Recap the same example, not a new one. The forward pass stored S=A XOR B and output SC+S′D. Restricting S gave D and C. Their XOR produced observability C XOR D. AND with activation S gave the decomposed test function. Partial composition of a candidate justified S=1 with A=0,B=1, producing 0110. CATAPULT reuses function information across target faults, while the example follows one fault for clarity.',()=>`${title('THE WHOLE ALGORITHM','One circuit, one consistent chain')}<div class="summary-chain">${[['Forward pass','S = A ⊕ B','F = SC + S′D'],['Backward pass','F|S=0 = D','F|S=1 = C'],['Observability','CO(S) = C ⊕ D','When does flipping S change F?'],['Test BDD','T₀ = S(C ⊕ D)','Activation AND observability'],['Composition','S=1 becomes A=0, B=1','Keep C=1, D=0'],['Verification','ABCD = 0110','Good F=1, faulty F=0']].map((r,i)=>`<div><span>${i+1}</span><h3>${r[0]}</h3><strong>${r[1]}</strong><p>${r[2]}</p></div>`).join('')}</div>`);
add('Sources and next questions',8,'SOURCES & NEXT STEPS',
 'The paper is the source for the algorithm stages. The book supports Boolean difference, BDDs, completeness, and the warning about BDD complexity. The previous group deck was consulted for structure; its worked example has been replaced. The current four-input example is original teaching content. Edge-case extensions such as incompatible paths, redundant faults, multiple outputs, branch versus stem faults, and variable ordering are intentionally deferred until the main walkthrough is understood. Finite BDDs can grow exponentially, not literally infinitely. The app uses an exact small-function BDD builder for diagrams, not the original CATAPULT implementation.',()=>layout(title('SOURCE DESK','Understand this path.<br>Then expand the story.')+`<div class="source-list"><p><strong>Gaede, Ross, Mercer & Butler, 1988</strong><br>CATAPULT, DAC pp. 597–600. Sections 2.3 and 3.1–3.4 guide the walkthrough.</p><p><strong>Bushnell & Agrawal, 2000</strong><br>Essentials of Electronic Testing, pp. 158–162 and 204.</p><p><strong>Earlier group deck</strong><br>Consulted for context. This circuit and its visual walkthrough are new.</p></div>`,`<div class="next-topics"><span class="eyebrow">POSSIBLE NEXT EXPANSIONS</span><h3>Conflicting paths<br>Redundancy proofs<br>Multiple outputs<br>Stem versus branch faults<br>BDD size and variable order</h3><p class="flat-note">These are deferred so the main example stays focused.</p><button class="start" data-go="4">Revisit the new circuit</button></div>`),`${sourcePaper} ${sourceBook}`);

function stopScan(update=false){clearInterval(timer);timer=null;const was=state.scanning;state.scanning=false;if(update&&was)render();}
function applyVector(i){state.A=i>>3;state.B=(i>>2)&1;state.C=(i>>1)&1;state.D=i&1;}
function scan(){if(state.scanning){stopScan(true);return;}state.scanning=true;state.scan=0;applyVector(0);render();timer=setInterval(()=>{if(state.scan===15){stopScan(true);return;}applyVector(++state.scan);render();},950);}
function syncMotion(){document.body.classList.toggle('motion-off',!state.motion);$('#motion').setAttribute('aria-pressed',String(state.motion));document.querySelectorAll('svg').forEach(s=>state.motion?s.unpauseAnimations?.():s.pauseAnimations?.());}
function render(){state.i=Math.max(0,Math.min(state.i,slides.length-1));const s=slides[state.i],entering=$('#stage .slide')?.dataset.index!==String(state.i),focus=document.activeElement?.dataset.bit;$('#stage').innerHTML=`<section class="slide teaching-slide ${entering?'entering':''}" data-index="${state.i}">${s.render()}</section>`;const h=$('#stage h1,#stage h2');if(h){h.id='slide-heading';$('#stage .slide').setAttribute('aria-labelledby','slide-heading');}$('#chapterNum').textContent=String(s.chapter).padStart(2,'0');$('#chapterLabel').textContent=s.section;$('#counter').innerHTML=`${String(state.i+1).padStart(2,'0')} <span>/ ${slides.length}</span>`;$('#progress>div').style.width=`${(state.i+1)/slides.length*100}%`;$('#prev').disabled=state.i===0;$('#next').disabled=state.i===slides.length-1;$('#noteTitle').textContent=s.name;$('#noteText').textContent=s.notes;$('#noteSource').textContent=s.source;document.title=`${state.i+1}. ${s.name} — CATAPULT`;document.querySelectorAll('.route-item,.equation,.summary-chain>div').forEach((el,i)=>el.style.setProperty('--order',i%5));if($('#traceBDD'))$('#traceBDD').onclick=()=>{state.trace=!state.trace;state.traceStep=state.trace?null:0;render();};if($('#nextDecision'))$('#nextDecision').onclick=()=>{const b=M.graphs[$('#stage [data-graph]').dataset.graph],t=M.trace(b,values());state.traceStep=state.trace?(state.traceStep===null?0:state.traceStep):0;state.trace=true;state.traceStep=state.traceStep>=t.steps.length?0:state.traceStep+1;render();};if($('#scan'))$('#scan').onclick=scan;syncMotion();if(focus)$(`[data-bit="${focus}"]`)?.focus();}
function go(i){stopScan();state.traceStep=null;document.documentElement.style.setProperty('--direction',i>=state.i?1:-1);state.i=Math.max(0,Math.min(i,slides.length-1));history.replaceState(null,'','#'+(state.i+1));render();$('#stage').scrollTop=0;$('#announcement').textContent=`Slide ${state.i+1}: ${slides[state.i].name}`;}
function overview(){stopScan();$('.modal-head .eyebrow').textContent='NAVIGATOR';$('.modal-head h2').textContent='CATAPULT walkthrough';$('#modalBody').innerHTML=`<div class="slide-grid">${slides.map((s,i)=>`<button data-go="${i}" class="${i===state.i?'current':''}"><small>${String(i+1).padStart(2,'0')} / ${s.section}</small>${s.name}</button>`).join('')}</div>`;$('#overlay').showModal();}
function toggleMotion(){state.motion=!state.motion;document.body.classList.add('motion-explicit');if(!state.motion)stopScan(true);syncMotion();}
function replay(){const s=$('#stage .slide');s.classList.remove('entering');void s.offsetWidth;s.classList.add('entering');}
function notes(){const n=$('#notesPanel');n.hidden=!n.hidden;$('#notes').setAttribute('aria-pressed',String(!n.hidden));}
function help(){$('.modal-head .eyebrow').textContent='PRESENTER CONTROLS';$('.modal-head h2').textContent='Explore at your pace';$('#modalBody').innerHTML=[['Next / previous','Right / Left'],['First / last','Home / End'],['Lecture map','O'],['Speaker notes','N'],['Replay animation','R'],['Toggle motion','M'],['Fullscreen','F']].map(a=>`<div class="shortcut-row"><span>${a[0]}</span><kbd>${a[1]}</kbd></div>`).join('')+'<p class="micro">Click inputs to explore live BDD paths. The composition slide has four selectable steps. Speaker notes are visible on this screen. Close them before projecting.</p>';$('#overlay').showModal();}
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{help();}}
$('#home').onclick=()=>go(0);$('#prev').onclick=()=>go(state.i-1);$('#next').onclick=()=>go(state.i+1);$('#overview').onclick=overview;$('#notes').onclick=notes;$('#closeNotes').onclick=notes;$('#help').onclick=help;$('#motion').onclick=toggleMotion;$('#replay').onclick=replay;$('#fullscreen').onclick=fullscreen;
document.addEventListener('click',ev=>{const t=ev.target.closest('button,[data-vector]');if(!t)return;if(t.hasAttribute('data-close'))$('#overlay').close();if(t.hasAttribute('data-go')){if($('#overlay').open)$('#overlay').close();go(+t.dataset.go);}if(t.dataset.bit){stopScan();state[t.dataset.bit]^=1;state.traceStep=null;render();}if(t.hasAttribute('data-branch')){state.branch=+t.dataset.branch;state.traceStep=null;render();}if(t.hasAttribute('data-compose')){state.compose=+t.dataset.compose;state.traceStep=null;render();}if(t.hasAttribute('data-vector')){stopScan();applyVector(+t.dataset.vector);render();}});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){$('#notesPanel').hidden=true;$('#notes').setAttribute('aria-pressed','false');return;}if($('#overlay').open)return;if(ev.target.matches('[data-vector]')&&[' ','Enter'].includes(ev.key)){ev.preventDefault();ev.target.click();return;}if(ev.target.matches('input,textarea,select')||ev.altKey||ev.ctrlKey||ev.metaKey)return;if(ev.key===' '&&ev.target.closest('button'))return;const k=ev.key.toLowerCase();if(['arrowright','pagedown',' '].includes(k)){ev.preventDefault();go(state.i+1);}else if(['arrowleft','pageup'].includes(k)){ev.preventDefault();go(state.i-1);}else if(k==='home'){ev.preventDefault();go(0);}else if(k==='end'){ev.preventDefault();go(slides.length-1);}else if(k==='o')overview();else if(k==='n')notes();else if(k==='r')replay();else if(k==='m')toggleMotion();else if(k==='f')fullscreen();else if(k==='?')help();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopScan(true);});
window.addEventListener('hashchange',()=>go((parseInt(location.hash.slice(1))||1)-1));
render();
